869	async function connectToPeer(uuid, name, ip) {
870	    // 如果已有活跃连接，直接打开聊天
871	    if (activeChats.has(uuid)) {
872	        openChat(uuid);
873	        return;
874	    }
875	
876	    // 获取对端 ws_port（从在线节点列表）
877	    const peer = onlinePeers.get(uuid);
878	    if (!peer) {
879	        showToast('对方不在线');
880	        return;
881	    }
882	
883	    openChat(uuid); // 先打开聊天窗口，显示"连接中..."
884	
885	    // 连接前先刷新自己的 token（token 每3秒更新，避免用过期的）
886	    try {
887	        const resp = await fetch('/api/me');
888	        const me = await resp.json();
889	        myInfo.token = me.token;
890	    } catch (e) { /* 刷新失败则用现有 token */ }
891	
892	    try {
893	        const peerPort = peer.ws_port || 50002;
894	        const wsUrl = `ws://${peer.ip}:${peerPort}/ws/chat`;
895	        const ws = new WebSocket(wsUrl);
896	
897	        ws.onopen = () => {
898	            // 发送连接请求，带上自己的 token 给对方后端验证
899	            // 对方通过 UDP 广播收到了我的 token，验证是否匹配
900	            ws.send(JSON.stringify({
901	                type: 'connect_request',
902	                uuid: myInfo.uuid,
903	                name: myInfo.name,
904	                token: myInfo.token,
905	                ip: myInfo.ip,
906	                ws_port: myInfo.ws_port,
907	            }));
908	        };
909	
910	        ws.onmessage = (e) => {
911	            const msg = JSON.parse(e.data);
912	            if (msg.type === 'connect_accepted') {
913	                activeChats.set(uuid, ws);
914	                connectedPeers.add(uuid);
915	                markConnected(uuid);
916	                setupPeerMessageHandler(uuid, ws);
917	                addSystemMessage(uuid, '连接已建立');
918	                updateChatHeaderStatus();
919	                renderOnlineList();
920	                renderContactsList();
921	                // 通知自己后端保存联系人（对方后端已保存，自己后端也需要记录）
922	                controlWs.send(JSON.stringify({
923	                    type: 'save_contact',
924	                    uuid: uuid,
925	                    name: name,
926	                    ip: ip,
927	                    ws_port: peer.ws_port || 50002,
928	                }));
929	            } else if (msg.type === 'connect_rejected') {
930	                ws.close();
931	                const reason = msg.reason === 'invalid_token' ? 'Token 验证失败，请稍后重试' : '对方拒绝了连接请求';
932	                addSystemMessage(uuid, reason);
933	                showToast(reason);
934	            }
935	        };
936	
937	        ws.onclose = () => {
938	            activeChats.delete(uuid);
939	            connectedPeers.delete(uuid);
940	            markDisconnected(uuid);
941	            renderOnlineList();
942	            renderContactsList();
943	            if (currentChat === uuid) {
944	                addSystemMessage(uuid, '连接已断开');
945	                updateChatHeaderStatus();
946	            }
947	        };
948	
949	        ws.onerror = () => {
950	            activeChats.delete(uuid);
951	            markDisconnected(uuid);
952	            addSystemMessage(uuid, '连接失败，请检查网络');
953	            showToast('连接失败');
954	            ws.close();
955	        };
956	
957	    } catch (e) {
958	        addSystemMessage(uuid, `连接失败: ${e.message}`);
959	    }
960	}
