1090	/** 为对端 WS 设置消息处理器（收到 connect_accepted 后调用） */
1091	function setupPeerMessageHandler(uuid, ws) {
1092	    ws.onmessage = (e) => {
1093	        const msg = JSON.parse(e.data);
1094	        if (msg.type === 'chat') {
1095	            // 对方发来的聊天消息（直接从 ws 收到时也需要处理）
1096	            handleDirectChatMessage(uuid, msg);
1097	        } else if (msg.type === 'file_request') {
1098	            // 对端后端通过 chat WS 发来的文件请求（HTTP relay 失败的 fallback）
1099	            // 先在自己后端注册 transfer，再弹窗确认
1100	            controlWs.send(JSON.stringify({
1101	                type: 'register_transfer',
1102	                transfer_id: msg.transfer_id,
1103	                file_name: msg.file_name,
1104	                file_size: msg.file_size,
1105	                chunk_size: msg.chunk_size,
1106	                total_chunks: msg.total_chunks,
1107	                from_uuid: uuid,
1108	                from_name: contacts.get(uuid) ? contacts.get(uuid).name : 'Unknown',
1109	            }));
1110	            // 用 from_uuid（chat WS 的对端 uuid）触发弹窗
1111	            showFileRequestModal({
1112	                transfer_id: msg.transfer_id,
1113	                file_name: msg.file_name,
1114	                file_size: msg.file_size,
1115	                from_uuid: uuid,
1116	                from_name: contacts.get(uuid) ? contacts.get(uuid).name : 'Unknown',
1117	            });
1118	        } else if (msg.type === 'file_response') {
1119	            // 对方对我方文件请求的响应
1120	            handleFileRequestResponse(msg);
1121	        } else if (msg.type === 'file_cancel') {
1122	            // 对方取消了传输
1123	            handleTransferCancelled(msg);
1124	        } else if (msg.type === 'ack') {
1125	            handleMessageAck(msg);
1126	        }
1127	    };
1128	}
