1130	function handleDirectChatMessage(uuid, msg) {
1131	    if (!contacts.has(uuid)) {
1132	        contacts.set(uuid, { name: msg.from_name, ip: '', status: 'online', messages: [] });
1133	    }
1134	    contacts.get(uuid).messages.push({
1135	        from: uuid,
1136	        content: msg.content,
1137	        msg_id: msg.msg_id,
1138	        timestamp: msg.timestamp,
1139	    });
1140	    // chat WS 直连绕过自己后端，需额外通知自己后端保存消息
1141	    controlWs.send(JSON.stringify({
1142	        type: 'save_message',
1143	        peer_uuid: uuid,
1144	        sender: uuid,
1145	        content: msg.content,
