1567	/**
1568	 * 开始分片上传文件到对方后端。
1569	 * 每发送一个分片后更新聊天气泡中的进度。
1570	 */
1571	async function startChunkUpload(transferId) {
1572	    const t = pendingFileTransfers[transferId];
1573	    if (!t) return;
1574	
1575	    const fileMsg = findFileMsgByTransferId(transferId);
1576	    if (fileMsg) {
1577	        fileMsg.status = 'uploading';
1578	        saveFileMessage(t.uuid, fileMsg);
1579	        if (currentChat === t.uuid) renderMessages(t.uuid);
1580	    }
1581	
1582	    const peer = onlinePeers.get(t.uuid);
1583	    if (!peer) {
1584	        showToast('对方不在线，无法发送文件');
1585	        if (fileMsg) {
1586	            fileMsg.status = 'failed';
1587	            saveFileMessage(t.uuid, fileMsg);
1588	            if (currentChat === t.uuid) renderMessages(t.uuid);
1589	        }
1590	        delete pendingFileTransfers[transferId];
1591	        return;
1592	    }
1593	
1594	    const file = t.file;
1595	    const CHUNK_SIZE = t.CHUNK_SIZE;
1596	    const totalChunks = t.totalChunks;
1597	    const peerPort = peer.ws_port || 50002;
1598	
1599	    for (let i = t.currentChunk; i < totalChunks; i++) {
1600	        // 检查连接是否被中断（断开连接 / 对方下线）
1601	        if (t.aborted) {
1602	            if (fileMsg) {
1603	                fileMsg.status = 'cancelled';
1604	                saveFileMessage(t.uuid, fileMsg);
1605	                if (currentChat === t.uuid) renderMessages(t.uuid);
1606	            }
1607	            return; // 连接中断，中止上传
1608	        }
1609	
1610	        const start = i * CHUNK_SIZE;
1611	        const end = Math.min(start + CHUNK_SIZE, file.size);
1612	        const blob = file.slice(start, end);
1613	        const dataB64 = await readAsBase64(blob);
1614	
1615	        let retries = 0;
1616	        let success = false;
1617	
1618	        while (retries < 3 && !success) {
1619	            try {
1620	                const resp = await fetch(`http://${peer.ip}:${peerPort}/api/transfer/chunk`, {
1621	                    method: 'POST',
1622	                    headers: { 'Content-Type': 'application/json' },
1623	                    body: JSON.stringify({
1624	                        transfer_id: transferId,
1625	                        chunk_index: i,
1626	                        data: dataB64,
1627	                    }),
1628	                });
1629	                if (resp.ok) {
1630	                    success = true;
1631	                    t.currentChunk = i + 1;
1632	                    // 更新进度条
1633	                    if (fileMsg) {
1634	                        fileMsg.progress = Math.round((i + 1) / totalChunks * 100);
1635	                        if (currentChat === t.uuid) renderMessages(t.uuid);
1636	                    }
1637	                } else {
1638	                    retries++;
1639	                }
1640	            } catch (e) {
1641	                retries++;
1642	            }
1643	        }
1644	
1645	        if (!success) {
1646	            t.failed = true;
1647	            if (fileMsg) {
1648	                fileMsg.status = 'failed';
1649	                saveFileMessage(t.uuid, fileMsg);
1650	                if (currentChat === t.uuid) renderMessages(t.uuid);
1651	            }
1652	            return; // 传输中断（保留 t 以便续传）
1653	        }
1654	    }
1655	
1656	    // 所有分片发送完毕 → 通知对方合并
1657	    try {
1658	        await fetch(`http://${peer.ip}:${peerPort}/api/transfer/complete`, {
1659	            method: 'POST',
1660	            headers: { 'Content-Type': 'application/json' },
1661	            body: JSON.stringify({ transfer_id: transferId }),
1662	        });
1663	        if (fileMsg) {
1664	            fileMsg.status = 'complete';
1665	            fileMsg.progress = 100;
1666	            saveFileMessage(t.uuid, fileMsg);
1667	            if (currentChat === t.uuid) renderMessages(t.uuid);
1668	        }
1669	    } catch (e) {
1670	        if (fileMsg) {
1671	            fileMsg.status = 'failed';
1672	            saveFileMessage(t.uuid, fileMsg);
1673	            if (currentChat === t.uuid) renderMessages(t.uuid);
1674	        }
1675	    }
1676	
1677	    delete pendingFileTransfers[transferId];
1678	}
